problem:
รูปหกเหลี่ยมหนึ่งถูกจารึกอยู่ในวงกลม: [asy]
pair pA, pB, pC, pD, pE, pF, pO;
pO = (0, 0);
pA = pO + dir(-10);
pB = pO + dir(60);
