label("$O$", O, S);
label("$P$", P, N);
[/asy]

translated_en:
Two runners $A$ and $B$ start at a point $O$ on a linear track and run in the same direction. Runner $B$ runs three times faster than $A$. An observer stands at point $P$, where $\overline{OP}$ is perpendicular to the track. Find the maximum value (in degrees) of $\angle APB$.

[asy]
unitsize(2 cm);

pair A, B, O, P;

A = (0.4,0);
B = (1.2,0);
O = (0,0);
P = (0,1);

draw((-0.5,0)--(2,0));
draw(O--P);
draw(P--A);
draw(P--B);

label("$A$", A, S);
label("$B$", B, S);
label("$O$", O, S);
label("$P$", P, N);
[/asy]

